patch:
diff --git a/tests/repro/win32-other-drive.js b/tests/repro/win32-other-drive.js
new file mode 100644
index 0000000..4d482da
--- /dev/null
+++ b/tests/repro/win32-other-drive.js
@@ -0,0 +1,78 @@
+/**
+ * @fileoverview Reproduction for "files on a different drive are not ignored on Windows".
+ * Emulates Windows path semantics on any OS: the shared `path` module is replaced by
+ * `path.win32` and `process.cwd()` returns a path on drive C: before ESLint is loaded.
+ * Run from the repo root: node tests/repro/win32-other-drive.js
+ */
+"use strict";
+
+/* eslint-disable no-console, no-underscore-dangle -- standalone reproduction script */
+
+const path = require("node:path");
+const Module = require("node:module");
+
+/*
+ * Hand `path.win32` to ESLint's own sources and to @eslint/config-array, so they compute paths
+ * exactly as on Windows, while Node's module loader and other dependencies keep the native `path`.
+ */
+const emulated = [path.resolve(__dirname, "../../lib"), path.dirname(require.resolve("@eslint/config-array"))];
+const originalLoad = Module._load;
+
+Module._load = function(request, parent, ...rest) {
+    if ((request === "path" || request === "node:path") && parent && emulated.some(dir => parent.filename.startsWith(dir))) {
+        return path.win32;
+    }
+    return originalLoad.call(this, request, parent, ...rest);
+};
+
+const CWD = "C:\\Project";
+
+process.cwd = () => CWD;
+
+const { Linter, ESLint } = require("../..");
+
+const cases = [
+    ["inside cwd (C:\\Project\\foo.js)", "C:\\Project\\foo.js", false],
+    ["same drive, outside cwd (C:\\other\\foo.js)", "C:\\other\\foo.js", true],
+    ["different drive (F:\\foo.js)", "F:\\foo.js", true]
+];
+
+const config = { rules: { "no-undef": "error" } };
+
+(async () => {
+    let failures = 0;
+
+    console.log(`process.cwd() = ${process.cwd()}`);
+    console.log(`path.relative(cwd, "F:\\\\foo.js") = ${JSON.stringify(path.win32.relative(CWD, "F:\\foo.js"))}`);
+    console.log(`path.relative(cwd, "C:\\\\other\\\\foo.js") = ${JSON.stringify(path.win32.relative(CWD, "C:\\other\\foo.js"))}\n`);
+
+    const eslint = new ESLint({ overrideConfigFile: true, overrideConfig: config });
+    const linter = new Linter({ configType: "flat" });
+
+    for (const [label, filePath, expectIgnored] of cases) {
+        const ignored = await eslint.isPathIgnored(filePath);
+        const [result] = await eslint.lintText("foo();", { filePath, warnIgnored: true });
+        const lintTextMessages = result.messages.map(m => `${m.ruleId ?? "(none)"}: ${m.message}`);
+        const lintTextIgnored = result.messages.length === 1 && /ignored/u.test(result.messages[0].message);
+        const linterMessages = linter.verify("foo();", config, filePath).map(m => `${m.ruleId ?? "(none)"}: ${m.message}`);
+        const linterLinted = linterMessages.some(m => m.startsWith("no-undef"));
+
+        const ok = ignored === expectIgnored &&
+            lintTextIgnored === expectIgnored &&
+            linterLinted === !expectIgnored;
+
+        if (!ok) {
+            failures++;
+        }
+
+        console.log(`${ok ? "OK  " : "BUG "} ${label} (expected ${expectIgnored ? "ignored" : "linted"})`);
+        console.log(`       ESLint#isPathIgnored -> ${ignored}`);
+        console.log(`       ESLint#lintText      -> ${JSON.stringify(lintTextMessages)}`);
+        console.log(`       Linter#verify        -> ${JSON.stringify(linterMessages)}`);
+    }
+
+    console.log(`\n${failures} case(s) behave incorrectly`);
+    process.exitCode = failures ? 1 : 0;
+})();
+
+/* eslint-enable no-console, no-underscore-dangle -- standalone reproduction script */
